// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

function isListSessionsFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'list_sessions';
}

async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type !== 'list_sessions') return;

  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }

  let summaries: SessionSummary[];
  try {
    summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    log.error('ws', 'listFor failed', {userId: session.userId, error: errorMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
    return;
  }

  sendSessionList(
    ws,
    summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
      entryCount: s.entryCount,
    }))
  );
}

